                 "text":  "전체집합 $U$의 공집합이 아닌 세 부분집합 $A$, $B$, $C$에서 두 조건 $p$, $q$에 대하여 p가 q이기 위한 필요충분조건인 것만을 보기에서 있는 대로 고른 것은?\n보기\nㄱ. $p: A-B=\\varnothing$   $q: A=B$\nㄴ. $p: A\\cap(B\\cup C)=B\\cup C$   $q: A\\cup(B\\cup C)=A$\nㄷ. $p: A^C\\cup B^C=U$   $q: A\\not\\subset B, B\\not\\subset A$",
