    "0845":  {
                 "section":  "07 명제와 절대부등식",
                 "text":  "다음은 자연수 $n$에 대하여 명제 \u0027$n^2$이 3의 배수이면 $n$도 3의 배수이다.\u0027가 참임을 그 대우를 이용하여 증명하는 과정이다.\n[증명]\n주어진 명제의 대우는 \u0027n이 3의 배수가 아니면 $n^2$도 3의 배수가 아니다.\u0027이다.\n$n=3k-2$ 또는 $n=(가)$ ($k$는 자연수)라 하면\n(i) $n=3k-2$일 때, $n^2=3((나))+1$\n(ii) $n=(가)$일 때, $n^2=3(3k^2-2k)+(다)$\n즉 $n^2$은 3으로 나누면 나머지가 1인 자연수가 되므로 n이 3의 배수가 아니면 $n^2$도 3의 배수가 아니다.\n따라서 주어진 명제의 대우가 참이므로 주어진 명제도 참이다.\n위의 과정에서 (가), (나)에 알맞은 식을 각각 $f(k)$, $g(k)$, (다)에 알맞은 수를 $a$라 할 때, $f(3a)+g(a)$의 값을 구하시오.",
                 "choices":  null,
                 "figure":  null
             },
