                 "section":  "07 명제와 절대부등식",
                 "text":  "대우를 이용하여 명제 \u0027실수 $a$, $b$에 대하여 $a^2+b^2=0$이면 $a=0$이고 $b=0$이다.\u0027가 참임을 증명하시오.",
